// A primitive example of how an API Gateway routes traffic
// Usually done with NGINX, AWS, or 'http-proxy-middleware' in Node.

const gatewayReq = { path: "/billing/invoice/123" };

function apiGatewayRouter(req) {
  console.log(`[Gateway] Received request from internet: ${req.path}`);

  // 1. Centralized Security Check
  console.log("[Gateway] Validating JWT... OK!");

  // 2. Routing logic
  if (req.path.startsWith("/users")) {
    console.log("[Gateway] Routing proxy to User Microservice (10.0.1.5)...");
  } 
  else if (req.path.startsWith("/billing")) {
    console.log("[Gateway] Routing proxy to Billing Microservice (10.0.1.8)...");
  }
  else {
    console.log("[Gateway] 404 Not Found");
  }
}

apiGatewayRouter(gatewayReq);
